"""Tests for scheduler priority computation — generated by platonic pipeline."""

from __future__ import annotations

from lintgate.specification.scheduler import _compute_priority


class TestComputePriority:
    """Exact-value tests for the priority scoring formula."""

    def test_all_defaults_returns_twenty(self):
        # coverage_depth="none" contributes 20, everything else 0
        assert _compute_priority() == 20.0

    def test_sigma_contribution_capped_at_40(self):
        # sigma=30 → min(30/30, 1.0) * 40 = 40
        assert _compute_priority(sigma=30) == 60.0  # 40 + 20 (none depth)
        # sigma=60 → min(60/30, 1.0) * 40 = 40 (capped)
        assert _compute_priority(sigma=60) == 60.0

    def test_sigma_scales_linearly_below_cap(self):
        # sigma=15 → min(15/30, 1.0) * 40 = 20
        assert _compute_priority(sigma=15) == 40.0  # 20 + 20 (none depth)

    def test_risk_score_contribution(self):
        # risk_score=1.0 → 30
        assert _compute_priority(risk_score=1.0) == 50.0  # 30 + 20

    def test_risk_score_fractional(self):
        # risk_score=0.5 → 15
        assert _compute_priority(risk_score=0.5) == 35.0  # 15 + 20

    def test_coverage_depth_none_adds_20(self):
        assert _compute_priority(coverage_depth="none") == 20.0

    def test_coverage_depth_sampled_adds_5(self):
        assert _compute_priority(coverage_depth="sampled") == 5.0

    def test_coverage_depth_profiled_adds_nothing(self):
        assert _compute_priority(coverage_depth="profiled") == 0.0

    def test_pure_with_hints_adds_10(self):
        assert _compute_priority(is_pure=True, has_hints=True, coverage_depth="profiled") == 10.0

    def test_pure_without_hints_adds_nothing(self):
        assert _compute_priority(is_pure=True, has_hints=False, coverage_depth="profiled") == 0.0

    def test_hints_without_pure_adds_nothing(self):
        assert _compute_priority(is_pure=False, has_hints=True, coverage_depth="profiled") == 0.0

    def test_contradicts_high_confidence_adds_15(self):
        score = _compute_priority(
            overlay_status="CONTRADICTS",
            overlay_confidence=0.7,
            coverage_depth="profiled",
        )
        assert score == 15.0

    def test_contradicts_low_confidence_no_boost(self):
        score = _compute_priority(
            overlay_status="CONTRADICTS",
            overlay_confidence=0.5,
            coverage_depth="profiled",
        )
        assert score == 0.0

    def test_no_empirical_data_adds_8(self):
        score = _compute_priority(
            overlay_status="NO_EMPIRICAL_DATA",
            coverage_depth="profiled",
        )
        assert score == 8.0

    def test_agrees_status_no_boost(self):
        score = _compute_priority(
            overlay_status="AGREES",
            overlay_confidence=0.9,
            coverage_depth="profiled",
        )
        assert score == 0.0

    def test_combined_maximum_priority(self):
        # sigma=30(40) + risk=1.0(30) + none(20) + pure+hints(10) + CONTRADICTS(15)
        score = _compute_priority(
            sigma=30,
            risk_score=1.0,
            is_pure=True,
            has_hints=True,
            coverage_depth="none",
            overlay_status="CONTRADICTS",
            overlay_confidence=0.9,
        )
        assert score == 115.0

    def test_ordering_high_sigma_beats_low(self):
        high = _compute_priority(sigma=30, coverage_depth="profiled")
        low = _compute_priority(sigma=5, coverage_depth="profiled")
        assert high > low

    def test_ordering_contradicts_beats_agrees(self):
        contradicts = _compute_priority(
            overlay_status="CONTRADICTS", overlay_confidence=0.8, coverage_depth="profiled"
        )
        agrees = _compute_priority(
            overlay_status="AGREES", overlay_confidence=0.8, coverage_depth="profiled"
        )
        assert contradicts > agrees
